macro_rules! Look {
    () => {
        # [doc = " The high-level intermediate representation for a look-around assertion."] # [doc = ""] # [doc = " An assertion match is always zero-length. Also called an \"empty match.\""] # [derive (Clone , Copy , Debug , Eq , PartialEq)] pub enum Look { # [doc = " Match the beginning of text. Specifically, this matches at the starting"] # [doc = " position of the input."] Start = 1 << 0 , # [doc = " Match the end of text. Specifically, this matches at the ending"] # [doc = " position of the input."] End = 1 << 1 , # [doc = " Match the beginning of a line or the beginning of text. Specifically,"] # [doc = " this matches at the starting position of the input, or at the position"] # [doc = " immediately following a `\\n` character."] StartLF = 1 << 2 , # [doc = " Match the end of a line or the end of text. Specifically, this matches"] # [doc = " at the end position of the input, or at the position immediately"] # [doc = " preceding a `\\n` character."] EndLF = 1 << 3 , # [doc = " Match the beginning of a line or the beginning of text. Specifically,"] # [doc = " this matches at the starting position of the input, or at the position"] # [doc = " immediately following either a `\\r` or `\\n` character, but never after"] # [doc = " a `\\r` when a `\\n` follows."] StartCRLF = 1 << 4 , # [doc = " Match the end of a line or the end of text. Specifically, this matches"] # [doc = " at the end position of the input, or at the position immediately"] # [doc = " preceding a `\\r` or `\\n` character, but never before a `\\n` when a `\\r`"] # [doc = " precedes it."] EndCRLF = 1 << 5 , # [doc = " Match an ASCII-only word boundary. That is, this matches a position"] # [doc = " where the left adjacent character and right adjacent character"] # [doc = " correspond to a word and non-word or a non-word and word character."] WordAscii = 1 << 6 , # [doc = " Match an ASCII-only negation of a word boundary."] WordAsciiNegate = 1 << 7 , # [doc = " Match a Unicode-aware word boundary. That is, this matches a position"] # [doc = " where the left adjacent character and right adjacent character"] # [doc = " correspond to a word and non-word or a non-word and word character."] WordUnicode = 1 << 8 , # [doc = " Match a Unicode-aware negation of a word boundary."] WordUnicodeNegate = 1 << 9 , # [doc = " Match the start of an ASCII-only word boundary. That is, this matches a"] # [doc = " position at either the beginning of the haystack or where the previous"] # [doc = " character is not a word character and the following character is a word"] # [doc = " character."] WordStartAscii = 1 << 10 , # [doc = " Match the end of an ASCII-only word boundary. That is, this matches"] # [doc = " a position at either the end of the haystack or where the previous"] # [doc = " character is a word character and the following character is not a word"] # [doc = " character."] WordEndAscii = 1 << 11 , # [doc = " Match the start of a Unicode word boundary. That is, this matches a"] # [doc = " position at either the beginning of the haystack or where the previous"] # [doc = " character is not a word character and the following character is a word"] # [doc = " character."] WordStartUnicode = 1 << 12 , # [doc = " Match the end of a Unicode word boundary. That is, this matches a"] # [doc = " position at either the end of the haystack or where the previous"] # [doc = " character is a word character and the following character is not a word"] # [doc = " character."] WordEndUnicode = 1 << 13 , # [doc = " Match the start half of an ASCII-only word boundary. That is, this"] # [doc = " matches a position at either the beginning of the haystack or where the"] # [doc = " previous character is not a word character."] WordStartHalfAscii = 1 << 14 , # [doc = " Match the end half of an ASCII-only word boundary. That is, this"] # [doc = " matches a position at either the end of the haystack or where the"] # [doc = " following character is not a word character."] WordEndHalfAscii = 1 << 15 , # [doc = " Match the start half of a Unicode word boundary. That is, this matches"] # [doc = " a position at either the beginning of the haystack or where the"] # [doc = " previous character is not a word character."] WordStartHalfUnicode = 1 << 16 , # [doc = " Match the end half of a Unicode word boundary. That is, this matches"] # [doc = " a position at either the end of the haystack or where the following"] # [doc = " character is not a word character."] WordEndHalfUnicode = 1 << 17 , }
    };
}

Look!();